-- Розділ «Часті запитання» (/chasti-zapytannya): таблиця faqs +
-- стартовий набір питань-відповідей. Відповіді написано у форматі
-- "answer-first" (перше речення — самодостатня, вичерпна відповідь на
-- питання із заголовка) — саме такий формат найкраще підхоплюють Google
-- AI Overviews/AI Mode та ChatGPT Search для прямого цитування.

CREATE TABLE IF NOT EXISTS faqs (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    question    VARCHAR(300) NOT NULL,
    answer      TEXT NOT NULL,
    sort_order  INT NOT NULL DEFAULT 0,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO faqs (question, answer, sort_order) VALUES
('Скільки коштує розробка сайту у Webservice Studio?',
 'Вартість сайту залежить від типу проєкту: лендинг, корпоративний сайт чи інтернет-магазин мають різну складність і ціну. Орієнтовні тарифи опубліковані на сторінці «Ціни», а точну вартість під ваш проєкт можна порахувати одразу на сторінці «Калькулятор» або отримати після короткого безкоштовного брифу.', 10),
('Скільки часу займає розробка сайту?',
 'Лендинг зазвичай готовий за кілька робочих днів, корпоративний сайт середньої складності — за 2-4 тижні, інтернет-магазин чи проєкт із нестандартним функціоналом — довше, залежно від обсягу. Точні терміни узгоджуються після брифу і фіксуються до початку робіт.', 20),
('Які послуги входять у розробку сайтів у Webservice Studio?',
 'Webservice Studio розробляє лендинги, корпоративні сайти та інтернет-магазини «під ключ»: від дизайну й верстки до бекенду, адмін-панелі для самостійного керування контентом і публікації на хостингу. Детальний перелік — на сторінці «Послуги».', 30),
('Чи розробляє Webservice Studio застосунки під Android?',
 'Так, студія розробляє застосунки під Android — від технічного завдання до публікації. Деталі й орієнтовну вартість можна побачити в розділі «Розробка додатків під Android» на сторінці «Послуги» або порахувати на калькуляторі.', 40),
('Що таке вайтпейдж, лендинг і клоакінг у послугах для арбітражу трафіку?',
 'Вайтпейдж — це "чиста" сторінка-обгортка, яку бачать модератори рекламних мереж і боти; лендинг — цільова сторінка, що веде відвідувача до конверсії; клоакінг — технологія, яка показує різний контент модераторам і реальним користувачам. Webservice Studio готує всі три типи сторінок під задачі арбітражу трафіку — детальніше в розділі «Арбітраж трафіку».', 50),
('Чи можна замовити лише адміністрування домену чи хостингу без розробки сайту?',
 'Так, адміністрування доменів і сайтів — окрема послуга: студія бере на супровід вже готовий сайт, домен або сервер без обов’язкового замовлення розробки з нуля. Орієнтовна вартість — у розділі «Адміністрування доменів та сайтів» на сторінці «Послуги».', 60),
('Як замовити проєкт або отримати консультацію?',
 'Найшвидший спосіб — заповнити форму на сторінці «Контакти» або написати напряму в Telegram чи WhatsApp, посилання є в тому ж розділі. Студія відповідає протягом дня і після короткого брифу озвучує терміни й вартість ще до старту робіт.', 70),
('Чи залишається сайт на підтримці після запуску?',
 'Так, після запуску сайт, домен і хостинг не лишаються без нагляду — студія на зв’язку, якщо потрібно щось донастроїти, оновити контент чи виправити помилку. Умови підтримки узгоджуються індивідуально під час обговорення проєкту.', 80);
